contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sent, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sent) + (amount)); require(sent <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);
        require(sent == 0 || sent == 10);

        // To make the payout branch possible, set up a prior nonzero pot if the caller asks for it.
        // This top-level call is needed for the property, but any revert here is not part of the rule.
        c.play{value: sent}(); if (__ESBMC_reverted()) return;

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        assert(
            reverted
                ? (potAfter == potBefore && cBalAfter == cBalBefore)
                : (
                    (potAfter == 0 && cBalAfter + 1 >= cBalBefore)
                    || (potAfter == potBefore + amount && cBalAfter == cBalBefore + amount)
                  )
        );
    }

    receive() external payable {}
}

