// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sent, uint256 amount) internal {
        sent = bound(sent, 0, 1000000000000000000000000000000);
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        vm.assume(address(this).balance >= amount);
        vm.assume(sent == 0 || sent == 10);
        try c.play{value: sent}() {} catch { return; }
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        assertTrue(reverted
                ? (potAfter == potBefore && cBalAfter == cBalBefore)
                : (
                    (potAfter == 0 && cBalAfter + 1 >= cBalBefore)
                    || (potAfter == potBefore + amount && cBalAfter == cBalBefore + amount)
                  ));
    }

    function testFuzz_run(uint256 sent, uint256 amount) public {
        _run(sent, amount);
    }

    receive() external payable {}
}
